/**
 * Cold-start splash. The fan-made Teal Koala (by u/otheast) sits on a full-bleed background.
 * Glow is the default. Tech, Radar, Circle and Ripple are chosen in settings.
 * Nothing but the icon and its motion is drawn. Holds for 1000ms, then fades over 300ms.
 */
public final class MorpheSplash {
    public static final String STYLE_GLOW = "linear";
    public static final String STYLE_TECH = "glyph";
    public static final String STYLE_RADAR = "radar";
    public static final String STYLE_CIRCLE = "bauhaus";
    public static final String STYLE_RIPPLE = "topo";

    private static boolean sEnabled = false;

    public static boolean isEnabled() {
        return sEnabled;
    }

    private static final String PREFS_NAME = "mighty_morphing";
    private static final String PREF_SPLASH_STYLE = "morphe_splash_style";

    private static final String KOALA_PART_1 = "";
    private static final String KOALA_PART_2 = "";
    private static Bitmap sKoalaBitmap;


    private static final int TEAL_SOFT = 0x1F2DD4BF;

    private MorpheSplash() {
    }

    public static String label(String style) {
        if (STYLE_TECH.equals(style)) return "Tech";
        if (STYLE_RADAR.equals(style)) return "Radar";
        if (STYLE_CIRCLE.equals(style)) return "Circle";
        if (STYLE_RIPPLE.equals(style)) return "Ripple";
        return "Glow";
    }

    public static synchronized Bitmap getKoalaBitmap() {
        if (sKoalaBitmap == null || sKoalaBitmap.isRecycled()) {
            try {
                byte[] bytes = Base64.decode(KOALA_PART_1 + KOALA_PART_2, Base64.DEFAULT);
                sKoalaBitmap = BitmapFactory.decodeByteArray(bytes, 0, bytes.length);
            } catch (Throwable ignored) {
            }
        }
        return sKoalaBitmap;
    }

    public static String normalizeStyle(String raw) {
        if (raw == null) return STYLE_GLOW;
        String s = raw.toLowerCase().trim();
        if (s.contains("glyph") || s.contains("tech") || s.contains("grid")) return STYLE_TECH;
        if (s.contains("radar")) return STYLE_RADAR;
        if (s.contains("bauhaus") || s.contains("circle")) return STYLE_CIRCLE;
        if (s.contains("topo") || s.contains("ripple")) return STYLE_RIPPLE;
        if (s.contains("linear") || s.contains("glow")) return STYLE_GLOW;
        return STYLE_GLOW;
    }

    public static String getActiveStyle(Context context, String defaultStyle) {
        try {
            SharedPreferences prefs = context.getApplicationContext()
                    .getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE);
            String saved = prefs.getString(PREF_SPLASH_STYLE, null);
            if (saved != null && !saved.trim().isEmpty()) return normalizeStyle(saved);
        } catch (Throwable ignored) {
        }
        return normalizeStyle(defaultStyle);
    }

    public static void setSplashStyle(Context context, String style) {
        try {
            context.getApplicationContext().getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
                    .edit().putString(PREF_SPLASH_STYLE, normalizeStyle(style)).apply();
        } catch (Throwable ignored) {
        }
    }

    public static void init(Activity activity) {
        init(activity, STYLE_GLOW);
    }

    public static void init(Activity activity, String configuredDefault) {
        if (activity == null) return;
        sEnabled = true;
        if (Build.VERSION.SDK_INT < 31) return;
        try {
            android.window.SplashScreen splashScreen = activity.getSplashScreen();
            if (splashScreen == null) return;
            splashScreen.setOnExitAnimationListener(splashView -> {
                // Hide Android's icon before any setting is read. A late read leaves that icon on screen.
                hideSystemIcon(splashView);
                if (!animationOn(activity)) {
                    dismissSplash(activity, splashView);
                    return;
                }
                try {
                    splashView.removeAllViews();
                    splashView.setClipChildren(false);
                    splashView.setClipToPadding(false);
                    Look look = resolve(activity);
                    play(activity, splashView, look.style, look.ink, look.art);
                } catch (Throwable ignored) {
                }
                new Handler(Looper.getMainLooper()).postDelayed(() -> leave(activity, splashView, 0), 900);
            });
        } catch (Throwable ignored) {
        }
    }

    /** Android draws the launcher icon into the splash view. Clear it before choosing a path. */
    private static void hideSystemIcon(View splashView) {
        try {
            splashView.setBackground(null);
            if (splashView instanceof android.window.SplashScreenView) {
                View icon = ((android.window.SplashScreenView) splashView).getIconView();
                if (icon != null) {
                    icon.setAlpha(0f);
                    icon.setVisibility(View.INVISIBLE);
                }
            }
        } catch (Throwable ignored) {
        }
    }

    /** Drops the splash without playing Android's icon exit, and without Joey's centred icon underneath. */
    private static void dismissSplash(Activity activity, View splashView) {
        try {
            if (activity.getWindow() != null) {
                activity.getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(0xFF000000));
            }
        } catch (Throwable ignored) {
        }
        try {
            splashView.setAlpha(0f);
            if (splashView instanceof ViewGroup) ((ViewGroup) splashView).removeAllViews();
            if (splashView instanceof android.window.SplashScreenView) {
                ((android.window.SplashScreenView) splashView).remove();
            }
        } catch (Throwable ignored) {
        }
    }

    /** Stops the moving parts, waits a moment if the feed is still empty, then fades off. */
    private static void leave(Activity activity, ViewGroup splashView, int waited) {
        try {
            clearMotion(splashView);
            if (waited < 700 && !feedReady(activity)) {
                new Handler(Looper.getMainLooper()).postDelayed(
                        () -> leave(activity, splashView, waited + 80), 80);
                return;
            }
            splashView.animate().alpha(0f).setDuration(180).withEndAction(() -> {
                try {
                    stop(splashView);
                    if (splashView instanceof android.window.SplashScreenView) {
                        ((android.window.SplashScreenView) splashView).remove();
                    }
                } catch (Throwable ignored) {
                }
            }).start();
        } catch (Throwable ignored) {
            try {
                if (splashView instanceof android.window.SplashScreenView) {
                    ((android.window.SplashScreenView) splashView).remove();
                }
            } catch (Throwable ignoredToo) {
            }
        }
    }

    private static boolean feedReady(Activity activity) {
        View decor = activity.getWindow() == null ? null : activity.getWindow().getDecorView();
        return decor != null && hasRows(decor);
    }

    private static boolean hasRows(View view) {
        if (view instanceof ViewGroup) {
            ViewGroup group = (ViewGroup) view;
            String name = view.getClass().getName();
            if (name.endsWith("RecyclerView") && group.getChildCount() > 0) return true;
            for (int i = 0; i < group.getChildCount(); i++) {
                if (hasRows(group.getChildAt(i))) return true;
            }
        }
        return false;
    }

    private static final String PREF_MATCH = "morphe_splash_match";
    private static final String PREF_ANIMATION = "morphe_splash_animate";
    private static final String PREF_LOGO = "morphe_splash_logo";
    private static final String PREF_LOGO_COLOR = "morphe_splash_logo_color";
    private static final String PREF_ANIM_COLOR = "morphe_splash_anim_color";
    private static final String LOGO_PLAIN = "plain";
    private static final String LOGO_HEADPHONES = "headphones";
    private static final String LOGO_GLASSES = "glasses";
    private static final String LOGO_FLOWER = "flower";
    private static final String LOGO_LEAF = "leaf";
    private static final String LOGO_BAMBOO = "bamboo";
    private static final String LOGO_SPARK = "spark";
    private static final String COLOR_AUTO = "auto";

    private static final class Look {
        final String style;
        final int ink;
        final Bitmap art;

        Look(String style, int ink, Bitmap art) {
            this.style = style;
            this.ink = ink;
            this.art = art;
        }
    }

    public static String summary(Context context) {
        if (!animationOn(context)) return "Off";
        if (matchesTheme(context)) return "Matches theme";
        return logoLabel(saved(context, PREF_LOGO, LOGO_HEADPHONES))
                + " · " + colorLabel(saved(context, PREF_LOGO_COLOR, ModernUi.ACCENT_BLUE))
                + " · " + label(getActiveStyle(context, STYLE_GLOW));
    }

    /** Settings chooser. Match theme follows the palette. The four rows underneath set each part. */
    public static void showPicker(Activity activity, Runnable saved) {
        float density = activity.getResources().getDisplayMetrics().density;
        final boolean[] match = { matchesTheme(activity) };
        final boolean[] disabled = { !animationOn(activity) };
        final String[] logo = { saved(activity, PREF_LOGO, LOGO_HEADPHONES) };
        final String[] logoColor = { saved(activity, PREF_LOGO_COLOR, ModernUi.ACCENT_BLUE) };
        final String[] motion = { getActiveStyle(activity, STYLE_GLOW) };
        final String[] motionColor = { saved(activity, PREF_ANIM_COLOR, COLOR_AUTO) };
        final String[] logos = { LOGO_PLAIN, LOGO_HEADPHONES, LOGO_GLASSES, LOGO_FLOWER, LOGO_LEAF, LOGO_BAMBOO, LOGO_SPARK };
        final String[] colors = {
                ModernUi.ACCENT_BLUE, ModernUi.ACCENT_TEAL, ModernUi.ACCENT_PURPLE, ModernUi.ACCENT_CORAL,
                ModernUi.ACCENT_MINT, ModernUi.ACCENT_GOLD, ModernUi.ACCENT_AMBER, ModernUi.ACCENT_BLACK,
                ModernUi.ACCENT_MONET
        };

        LinearLayout page = MorpheDialog.page(activity, "Splash", null);
        android.widget.CheckBox motionOn = MorpheDialog.check(activity, "Disable animation", disabled[0], null);
        android.widget.CheckBox follow = MorpheDialog.check(activity, "Match theme", match[0], null);

        FrameLayout stage = new FrameLayout(activity);
        stage.setClipChildren(true);
        int radius = Math.round(16 * density);
        stage.setOutlineProvider(new ViewOutlineProvider() {
            @Override
            public void getOutline(View view, Outline outline) {
                outline.setRoundRect(0, 0, view.getWidth(), view.getHeight(), radius);
            }
        });
        stage.setClipToOutline(true);

        LinearLayout options = new LinearLayout(activity);
        options.setOrientation(LinearLayout.VERTICAL);
        ImageView[] faces = new ImageView[logos.length];
        View[] dots = new View[colors.length];
        TextView[] motions = new TextView[5];
        View[] inks = new View[colors.length + 1];
        final String[] motionKeys = { STYLE_GLOW, STYLE_TECH, STYLE_RADAR, STYLE_CIRCLE, STYLE_RIPPLE };

        final TextView[] replayHold = new TextView[1];
        Runnable paint = () -> {
            boolean off = disabled[0];
            stage.setAlpha(off ? 0.38f : 1f);
            follow.setEnabled(!off);
            follow.setAlpha(off ? 0.38f : 1f);
            options.setAlpha(off || match[0] ? 0.38f : 1f);
            if (replayHold[0] != null) replayHold[0].setAlpha(off ? 0.38f : 1f);
            for (int i = 0; i < faces.length; i++) {
                boolean on = logos[i].equals(logo[0]);
                faces[i].setAlpha(on ? 1f : 0.55f);
                GradientDrawable ring = new GradientDrawable();
                ring.setShape(GradientDrawable.OVAL);
                ring.setColor(0x00000000);
                if (on) ring.setStroke(Math.round(2 * density), MorpheDialog.accent(activity));
                faces[i].setBackground(ring);
            }
            for (int i = 0; i < dots.length; i++) {
                paintSwatch(dots[i], swatch(activity, colors[i]), colors[i].equals(logoColor[0]));
            }
            for (int i = 0; i < motions.length; i++) {
                boolean on = motionKeys[i].equals(motion[0]);
                motions[i].setTextColor(on ? MorpheDialog.accent(activity) : MorpheDialog.text(activity));
            }
            int autoTint = lift(swatch(activity, logoColor[0]));
            paintSwatch(inks[0], autoTint, COLOR_AUTO.equals(motionColor[0]));
            ((TextView) inks[0]).setTextColor(Color.luminance(autoTint) > 0.6f ? 0xFF111827 : 0xFFF8FAFC);
            for (int i = 0; i < colors.length; i++) {
                paintSwatch(inks[i + 1], swatch(activity, colors[i]), colors[i].equals(motionColor[0]));
            }
            refreshWheels(options);
        };
        Runnable play = () -> {
            if (disabled[0]) return;
            Look look = match[0]
                    ? matched(activity)
                    : manual(activity, logo[0], logoColor[0], motion[0], motionColor[0]);
            play(activity, stage, look.style, look.ink, look.art);
        };
        follow.setOnCheckedChangeListener((button, checked) -> {
            if (disabled[0]) return;
            match[0] = checked;
            paint.run();
            play.run();
        });
        motionOn.setOnCheckedChangeListener((button, checked) -> {
            disabled[0] = checked;
            paint.run();
            if (checked) clearMotion(stage);
            else play.run();
        });

        options.addView(MorpheDialog.section(activity, "Logo", MorpheDialog.sub(activity)));
        options.addView(faceRow(activity, density, logos, faces, () -> disabled[0] || match[0], logo, paint, play));
        options.addView(MorpheDialog.section(activity, "Logo colour", MorpheDialog.sub(activity)));
        options.addView(dotRow(activity, colors, dots, () -> disabled[0] || match[0], logoColor, paint, play,
                "Match animation", () -> COLOR_AUTO.equals(motionColor[0])
                        ? lift(swatch(activity, logoColor[0]))
                        : swatch(activity, motionColor[0])));
        options.addView(MorpheDialog.section(activity, "Motion", MorpheDialog.sub(activity)));
        Flow motionRow = new Flow(activity, density);
        for (int i = 0; i < motionKeys.length; i++) {
            TextView chip = MorpheDialog.action(activity, label(motionKeys[i]), MorpheDialog.TEXT);
            int index = i;
            chip.setOnClickListener(v -> {
                if (disabled[0] || match[0]) return;
                motion[0] = motionKeys[index];
                paint.run();
                play.run();
            });
            motions[i] = chip;
            motionRow.addView(chip);
        }
        options.addView(motionRow);
        options.addView(MorpheDialog.section(activity, "Animation colour", MorpheDialog.sub(activity)));
        options.addView(inkRow(activity, colors, inks, () -> disabled[0] || match[0], motionColor, paint, play,
                "Match logo", () -> swatch(activity, logoColor[0])));
        paint.run();

        int previewH = Math.round(200 * density);
        page.addView(stage, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, previewH));
        page.addView(motionOn);
        page.addView(follow);
        page.addView(options);

        TextView replay = MorpheDialog.action(activity, "Replay", MorpheDialog.GOLD);
        TextView cancel = MorpheDialog.action(activity, "Cancel", MorpheDialog.SUB);
        TextView save = MorpheDialog.action(activity, "Save", MorpheDialog.GOLD);
        replayHold[0] = replay;
        paint.run();
        page.addView(MorpheDialog.actions(activity, replay, cancel, save));
        AlertDialog[] shown = new AlertDialog[1];
        replay.setOnClickListener(v -> {
            if (disabled[0]) return;
            play.run();
        });
        cancel.setOnClickListener(v -> {
            if (shown[0] != null) shown[0].dismiss();
        });
        save.setOnClickListener(v -> {
            SharedPreferences prefs = activity.getApplicationContext()
                    .getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE);
            rememberAnimation(!disabled[0]);
            prefs.edit()
                    .putBoolean(PREF_ANIMATION, !disabled[0])
                    .putBoolean(PREF_MATCH, match[0])
                    .putString(PREF_LOGO, logo[0])
                    .putString(PREF_LOGO_COLOR, logoColor[0])
                    .putString(PREF_SPLASH_STYLE, motion[0])
                    .putString(PREF_ANIM_COLOR, motionColor[0])
                    .apply();
            if (saved != null) saved.run();
            if (shown[0] != null) shown[0].dismiss();
        });
        shown[0] = MorpheDialog.show(activity, page, 560);
        stage.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener() {
            @Override
            public void onViewAttachedToWindow(View v) {
            }

            @Override
            public void onViewDetachedFromWindow(View v) {
                stop(stage);
            }
        });
        stage.post(() -> {
            if (!disabled[0]) play.run();
        });
    }

    private static View faceRow(Activity activity, float density, String[] logos, ImageView[] faces,
                                java.util.concurrent.Callable<Boolean> locked, String[] chosen,
                                Runnable paint, Runnable play) {
        Flow row = new Flow(activity, density);
        int size = Math.round(36 * density);
        for (int i = 0; i < logos.length; i++) {
            ImageView face = new ImageView(activity);
            Bitmap bitmap = SplashArt.character(logos[i]);
            if (bitmap != null) face.setImageBitmap(bitmap);
            face.setScaleType(ImageView.ScaleType.FIT_CENTER);
            face.setPadding(4, 4, 4, 4);
            int index = i;
            face.setOnClickListener(v -> {
                try {
                    if (locked.call()) return;
                } catch (Exception ignored) {
                    return;
                }
                chosen[0] = logos[index];
                paint.run();
                play.run();
            });
            row.addView(face, new ViewGroup.LayoutParams(size, size));
            faces[i] = face;
        }
        return row;
    }

    private static View dotRow(Activity activity, String[] colors, View[] dots,
                               java.util.concurrent.Callable<Boolean> locked, String[] chosen,
                               Runnable paint, Runnable play, String matchLabel,
                               java.util.function.IntSupplier matchColor) {
        LinearLayout row = colourRow(activity);
        for (int i = 0; i < colors.length; i++) {
            View dot = new View(activity);
            int index = i;
            dot.setOnClickListener(v -> {
                try {
                    if (locked.call()) return;
                } catch (Exception ignored) {
                    return;
                }
                chosen[0] = colors[index];
                paint.run();
                play.run();
            });
            row.addView(dot, colourChip(activity));
            dots[i] = dot;
        }
        row.addView(wheelChip(activity, locked, chosen, paint, play, matchLabel, matchColor), colourChip(activity));
        return row;
    }

    private static View inkRow(Activity activity, String[] colors, View[] inks,
                               java.util.concurrent.Callable<Boolean> locked, String[] chosen,
                               Runnable paint, Runnable play, String matchLabel,
                               java.util.function.IntSupplier matchColor) {
        LinearLayout row = colourRow(activity);
        TextView auto = new TextView(activity);
        auto.setText("A");
        auto.setGravity(Gravity.CENTER);
        auto.setTextSize(11);
        auto.setOnClickListener(v -> {
            try {
                if (locked.call()) return;
            } catch (Exception ignored) {
                return;
            }
            chosen[0] = COLOR_AUTO;
            paint.run();
            play.run();
        });
        inks[0] = auto;
        for (int i = 0; i < colors.length; i++) {
            View dot = new View(activity);
            int index = i;
            dot.setOnClickListener(v -> {
                try {
                    if (locked.call()) return;
                } catch (Exception ignored) {
                    return;
                }
                chosen[0] = colors[index];
                paint.run();
                play.run();
            });
            row.addView(dot, colourChip(activity));
            inks[i + 1] = dot;
        }
        row.addView(wheelChip(activity, locked, chosen, paint, play, matchLabel, matchColor), colourChip(activity));
        row.addView(auto, colourChip(activity));
        return row;
    }

    private static void paintSwatch(View view, int color, boolean on) {
        GradientDrawable circle = new GradientDrawable();
        circle.setShape(GradientDrawable.OVAL);
        circle.setColor(color);
        float density = view.getResources().getDisplayMetrics().density;
        if (on) circle.setStroke(Math.round(2 * density), 0xFFF8FAFC);
        else if (Color.red(color) + Color.green(color) + Color.blue(color) > 680) {
            circle.setStroke(Math.round(density), 0x66FFFFFF);
        }
        view.setBackground(circle);
    }

    private static View wheelChip(Activity activity,
                                  java.util.concurrent.Callable<Boolean> locked, String[] chosen,
                                  Runnable paint, Runnable play, String matchLabel,
                                  java.util.function.IntSupplier matchColor) {
        WheelChip chip = new WheelChip(activity, chosen);
        chip.setOnClickListener(v -> {
            try {
                if (locked.call()) return;
            } catch (Exception ignored) {
                return;
            }
            showWheel(activity, swatch(activity, chosen[0]), matchLabel, matchColor, color -> {
                chosen[0] = String.format(Locale.US, "#%06X", (0xFFFFFF & color));
                paint.run();
                play.run();
            });
        });
        return chip;
    }

    private static void refreshWheels(View view) {
        if (view instanceof WheelChip) view.invalidate();
        if (view instanceof ViewGroup) {
            ViewGroup group = (ViewGroup) view;
            for (int i = 0; i < group.getChildCount(); i++) refreshWheels(group.getChildAt(i));
        }
    }

    private static void showWheel(Activity activity, int initial, String matchLabel,
                                  java.util.function.IntSupplier matchColor,
                                  java.util.function.IntConsumer picked) {
        float density = activity.getResources().getDisplayMetrics().density;
        float[] hsv = new float[3];
        Color.colorToHSV(initial, hsv);
        if (hsv[1] < 0.2f) hsv[1] = 1f;
        final float[] hue = { hsv[0] };
        final float[] value = { hsv[2] };
        LinearLayout page = MorpheDialog.page(activity, "Colour", null);
        View preview = new View(activity);
        Runnable paint = () -> paintSwatch(preview, Color.HSVToColor(new float[]{ hue[0], hsv[1], value[0] }), true);
        ValueBar[] valueBar = new ValueBar[1];
        HueBar hueBar = new HueBar(activity, hue, () -> {
            paint.run();
            if (valueBar[0] != null) valueBar[0].invalidate();
        });
        valueBar[0] = new ValueBar(activity, hue, value, hsv[1], paint);
        int barH = Math.round(28 * density);
        page.addView(preview, new LinearLayout.LayoutParams(Math.round(36 * density), Math.round(36 * density)));
        page.addView(hueBar, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, barH));
        LinearLayout.LayoutParams valueParams = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, barH);
        valueParams.topMargin = Math.round(12 * density);
        page.addView(valueBar[0], valueParams);
        paint.run();
        TextView match = MorpheDialog.action(activity, matchLabel, MorpheDialog.GOLD);
        TextView use = MorpheDialog.action(activity, "Use", MorpheDialog.GOLD);
        TextView cancel = MorpheDialog.action(activity, "Cancel", MorpheDialog.SUB);
        page.addView(MorpheDialog.actions(activity, match, cancel, use));
        AlertDialog[] shown = new AlertDialog[1];
        match.setOnClickListener(v -> {
            float[] matched = new float[3];
            Color.colorToHSV(matchColor.getAsInt(), matched);
            hue[0] = matched[0];
            value[0] = matched[2];
            if (matched[1] > 0.2f) hsv[1] = matched[1];
            paint.run();
            hueBar.invalidate();
            if (valueBar[0] != null) valueBar[0].invalidate();
        });
        cancel.setOnClickListener(v -> {
            if (shown[0] != null) shown[0].dismiss();
        });
        use.setOnClickListener(v -> {
            picked.accept(Color.HSVToColor(new float[]{ hue[0], hsv[1], value[0] }));
            if (shown[0] != null) shown[0].dismiss();
        });
        shown[0] = MorpheDialog.show(activity, page, 360);
    }

    private static void play(Activity activity, FrameLayout root, String style, int ink, Bitmap art) {
        if (root.getWidth() <= 0 || root.getHeight() <= 0) {
            root.post(() -> play(activity, root, style, ink, art));
            return;
        }
        stop(root);
        float density = activity.getResources().getDisplayMetrics().density;
        int min = Math.min(root.getWidth(), root.getHeight());
        float fraction = min >= Math.round(480 * density) ? 0.20f : 0.40f;
        int icon = Math.round(Math.min(min * fraction, 168 * density));
        icon = Math.max(icon, Math.round(72 * density));
        String resolved = normalizeStyle(style);
        ArrayList<Object> running = new ArrayList<>();
        root.setTag(running);
        if (STYLE_TECH.equals(resolved)) buildTech(activity, root, density, icon, running, ink, art);
        else if (STYLE_RADAR.equals(resolved)) buildRadar(activity, root, density, icon, running, ink, art);
        else if (STYLE_CIRCLE.equals(resolved)) buildCircle(activity, root, density, icon, running, ink, art);
        else if (STYLE_RIPPLE.equals(resolved)) buildRipple(activity, root, density, icon, running, ink, art);
        else buildGlow(activity, root, density, icon, running, ink, art);
    }

    private static boolean sAnimateCached;
    private static boolean sAnimate = true;

    /** On by default. Off skips the moving splash and opens the app straight away. */
    private static boolean animationOn(Context context) {
        if (sAnimateCached) return sAnimate;
        try {
            sAnimate = context.getApplicationContext()
                    .getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
                    .getBoolean(PREF_ANIMATION, true);
        } catch (Throwable ignored) {
            sAnimate = true;
        }
        sAnimateCached = true;
        return sAnimate;
    }

    private static void rememberAnimation(boolean on) {
        sAnimate = on;
        sAnimateCached = true;
    }

    private static boolean matchesTheme(Context context) {
        try {
            return context.getApplicationContext().getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
                    .getBoolean(PREF_MATCH, true);
        } catch (Throwable ignored) {
            return true;
        }
    }

    private static String saved(Context context, String key, String fallback) {
        try {
            String value = context.getApplicationContext().getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
                    .getString(key, fallback);
            return value == null || value.trim().isEmpty() ? fallback : value;
        } catch (Throwable ignored) {
            return fallback;
        }
    }

    private static Look resolve(Context context) {
        if (matchesTheme(context)) return matched(context);
        return manual(context,
                saved(context, PREF_LOGO, LOGO_HEADPHONES),
                saved(context, PREF_LOGO_COLOR, ModernUi.ACCENT_BLUE),
                getActiveStyle(context, STYLE_GLOW),
                saved(context, PREF_ANIM_COLOR, COLOR_AUTO));
    }

    private static Look matched(Context context) {
        String theme = ModernUi.getMaterialAccent(context);
        if (ModernUi.isPureAmoled(context)) theme = ModernUi.ACCENT_AMOLED;
        String logo = logoFor(theme);
        int fur = swatch(context, ModernUi.ACCENT_AMOLED.equals(theme) ? ModernUi.ACCENT_BLUE : theme);
        return new Look(STYLE_GLOW, lift(fur), SplashArt.recolor(logo, fur));
    }

    private static Look manual(Context context, String logo, String logoColor, String style, String motionColor) {
        int fur = swatch(context, logoColor);
        int ink = COLOR_AUTO.equals(motionColor) ? lift(fur) : swatch(context, motionColor);
        return new Look(style, ink, SplashArt.recolor(logo, fur));
    }

    private static String logoFor(String theme) {
        if (ModernUi.ACCENT_TEAL.equalsIgnoreCase(theme)) return LOGO_PLAIN;
        if (ModernUi.ACCENT_PURPLE.equalsIgnoreCase(theme)) return LOGO_GLASSES;
        if (ModernUi.ACCENT_CORAL.equalsIgnoreCase(theme)) return LOGO_FLOWER;
        if (ModernUi.ACCENT_MINT.equalsIgnoreCase(theme)) return LOGO_LEAF;
        if (ModernUi.ACCENT_GOLD.equalsIgnoreCase(theme)) return LOGO_BAMBOO;
        if (ModernUi.ACCENT_AMBER.equalsIgnoreCase(theme)) return LOGO_SPARK;
        return LOGO_HEADPHONES;
    }

    private static String logoLabel(String logo) {
        if (LOGO_HEADPHONES.equals(logo)) return "Headphones";
        if (LOGO_GLASSES.equals(logo)) return "Glasses";
        if (LOGO_FLOWER.equals(logo)) return "Flower";
        if (LOGO_LEAF.equals(logo)) return "Leaf";
        if (LOGO_BAMBOO.equals(logo)) return "Bamboo";
        if (LOGO_SPARK.equals(logo)) return "Spark";
        return "Plain";
    }

    private static String colorLabel(String color) {
        if (ModernUi.ACCENT_TEAL.equalsIgnoreCase(color)) return "Aqua";
        if (ModernUi.ACCENT_PURPLE.equalsIgnoreCase(color)) return "Purple";
        if (ModernUi.ACCENT_CORAL.equalsIgnoreCase(color)) return "Coral";
        if (ModernUi.ACCENT_MINT.equalsIgnoreCase(color)) return "Mint";
        if (ModernUi.ACCENT_GOLD.equalsIgnoreCase(color)) return "Gold";
        if (ModernUi.ACCENT_AMBER.equalsIgnoreCase(color)) return "Amber";
        if (ModernUi.ACCENT_BLACK.equalsIgnoreCase(color)) return "Black";
        if (ModernUi.ACCENT_MONET.equalsIgnoreCase(color)) return "Sky";
        if (ModernUi.ACCENT_AMOLED.equalsIgnoreCase(color)) return "AMOLED";
        if (color != null && color.startsWith("#")) return "Custom";
        return "Blue";
    }

    private static int swatch(Context context, String color) {
        if (color != null && color.startsWith("#")) {
            try {
                return Color.parseColor(color);
            } catch (Throwable ignored) {
            }
        }
        if (ModernUi.ACCENT_TEAL.equalsIgnoreCase(color)) return ModernUi.COLOR_TEAL;
        if (ModernUi.ACCENT_PURPLE.equalsIgnoreCase(color)) return ModernUi.COLOR_PURPLE;
        if (ModernUi.ACCENT_CORAL.equalsIgnoreCase(color)) return ModernUi.COLOR_CORAL;
        if (ModernUi.ACCENT_MINT.equalsIgnoreCase(color)) return ModernUi.COLOR_MINT;
        if (ModernUi.ACCENT_GOLD.equalsIgnoreCase(color)) return ModernUi.COLOR_GOLD;
        if (ModernUi.ACCENT_AMBER.equalsIgnoreCase(color)) return ModernUi.COLOR_AMBER;
        if (ModernUi.ACCENT_BLACK.equalsIgnoreCase(color)) return ModernUi.COLOR_BLACK;
        if (ModernUi.ACCENT_MONET.equalsIgnoreCase(color)) return ModernUi.getPalette(context).accent;
        return ModernUi.COLOR_BLUE;
    }

    private static int lift(int color) {
        float[] hsv = new float[3];
        Color.colorToHSV(color, hsv);
        // Aqua is next to blue. The usual hue step turns this splash blue, so only the brightness moves.
        if ((color & 0x00FFFFFF) == (ModernUi.COLOR_TEAL & 0x00FFFFFF)) {
            hsv[2] = Math.min(1f, hsv[2] + 0.14f);
            return Color.HSVToColor(hsv);
        }
        if (hsv[1] < 0.15f) {
            hsv[0] = 206f;
            hsv[1] = 0.28f;
            hsv[2] = Math.min(1f, hsv[2]);
        } else {
            hsv[0] = (hsv[0] + 32f) % 360f;
            hsv[2] = Math.min(1f, hsv[2] + 0.14f);
        }
        return Color.HSVToColor(hsv);
    }

    private static int dye(int color, int alpha) {
        return (color & 0x00FFFFFF) | (alpha << 24);
    }

    private static void stop(ViewGroup root) {
        Object tag = root.getTag();
        if (tag instanceof ArrayList) {
            for (Object item : (ArrayList<?>) tag) {
                if (item instanceof Animator) ((Animator) item).cancel();
            }
            ((ArrayList<?>) tag).clear();
        }
        clearMotion(root);
        root.removeAllViews();
    }

    private static void clearMotion(ViewGroup root) {
        for (int i = 0; i < root.getChildCount(); i++) {
            View child = root.getChildAt(i);
            child.animate().cancel();
            child.clearAnimation();
            if (child instanceof ViewGroup) clearMotion((ViewGroup) child);
        }
    }

    private static void track(ArrayList<Object> running, Animator animator) {
        running.add(animator);
        animator.start();
    }

    private static void track(ArrayList<Object> running, View view, Animation animation) {
        running.add(animation);
        view.startAnimation(animation);
    }

    private static ImageView koala(Activity activity, FrameLayout root, int size, Bitmap art) {
        ImageView view = new ImageView(activity);
        Bitmap bitmap = art != null ? art : getKoalaBitmap();
        if (bitmap != null) view.setImageBitmap(bitmap);
        view.setScaleType(ImageView.ScaleType.FIT_CENTER);
        root.addView(view, new FrameLayout.LayoutParams(size, size, Gravity.CENTER));
        return view;
    }

    private static void buildGlow(Activity activity, FrameLayout root, float density, int icon, ArrayList<Object> running, int ink, Bitmap art) {
        root.setBackgroundColor(0xFF070A0F);
        View glow = new View(activity);
        GradientDrawable disc = new GradientDrawable();
        disc.setShape(GradientDrawable.OVAL);
        disc.setGradientType(GradientDrawable.RADIAL_GRADIENT);
        disc.setGradientRadius(icon * 1.35f);
        disc.setColors(new int[]{ dye(ink, 0x55), dye(ink, 0x22), 0x00070A0F });
        glow.setBackground(disc);
        int glowSize = Math.round(icon * 2.6f);
        root.addView(glow, new FrameLayout.LayoutParams(glowSize, glowSize, Gravity.CENTER));
        glow.setAlpha(0f);
        glow.setScaleX(0.75f);
        glow.setScaleY(0.75f);
        glow.animate().alpha(1f).scaleX(1.15f).scaleY(1.15f).setDuration(700)
                .setInterpolator(new DecelerateInterpolator()).start();

        ImageView mark = koala(activity, root, icon, art);
        mark.setAlpha(0f);
        mark.setScaleX(0.92f);
        mark.setScaleY(0.92f);
        mark.animate().alpha(1f).scaleX(1f).scaleY(1f).setStartDelay(80).setDuration(500)
                .setInterpolator(new DecelerateInterpolator()).start();
    }

    private static void buildTech(Activity activity, FrameLayout root, float density, int icon, ArrayList<Object> running, int ink, Bitmap art) {
        root.setBackgroundColor(0xFF040404);
        View dots = new View(activity) {
            private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);
            @Override
            protected void onDraw(Canvas canvas) {
                paint.setColor(dye(ink, 0x1F));
                float step = 12f * density;
                float radius = density;
                for (float x = step / 2f; x < getWidth(); x += step) {
                    for (float y = step / 2f; y < getHeight(); y += step) {
                        canvas.drawCircle(x, y, radius, paint);
                    }
                }
            }
        };
        root.addView(dots, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));

        View scan = new View(activity);
        scan.setBackground(new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,
                new int[]{ dye(ink, 0x00), dye(ink, 0x55), dye(ink, 0x00) }));
        int band = Math.round(48 * density);
        root.addView(scan, new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, band));
        ObjectAnimator sweep = ObjectAnimator.ofFloat(scan, "translationY", -band, root.getHeight() + band);
        sweep.setDuration(1800);
        sweep.setRepeatCount(ValueAnimator.INFINITE);
        sweep.setInterpolator(new AccelerateDecelerateInterpolator());
        track(running, sweep);

        int box = Math.round(icon * 1.22f);
        View brackets = new View(activity) {
            private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);
            @Override
            protected void onDraw(Canvas canvas) {
                paint.setStyle(Paint.Style.STROKE);
                paint.setStrokeWidth(2f * density);
                paint.setColor(dye(ink, 0xCC));
                float arm = 12f * density;
                float w = getWidth();
                float h = getHeight();
                canvas.drawLine(0, 0, arm, 0, paint);
                canvas.drawLine(0, 0, 0, arm, paint);
                canvas.drawLine(w, 0, w - arm, 0, paint);
                canvas.drawLine(w, 0, w, arm, paint);
                canvas.drawLine(0, h, arm, h, paint);
                canvas.drawLine(0, h, 0, h - arm, paint);
                canvas.drawLine(w, h, w - arm, h, paint);
                canvas.drawLine(w, h, w, h - arm, paint);
            }
        };
        root.addView(brackets, new FrameLayout.LayoutParams(box, box, Gravity.CENTER));
        brackets.setAlpha(0f);
        brackets.setScaleX(1.18f);
        brackets.setScaleY(1.18f);
        brackets.animate().alpha(1f).scaleX(1f).scaleY(1f).setStartDelay(240).setDuration(420)
                .setInterpolator(new DecelerateInterpolator()).start();

        ImageView mark = koala(activity, root, icon, art);
        mark.setAlpha(0f);
        mark.postDelayed(() -> mark.setAlpha(0.35f), 50);
        mark.postDelayed(() -> mark.setAlpha(0.1f), 100);
        mark.postDelayed(() -> mark.setAlpha(1f), 180);
    }

    private static void buildRadar(Activity activity, FrameLayout root, float density, int icon, ArrayList<Object> running, int ink, Bitmap art) {
        root.setBackgroundColor(0xFF070A10);
        int outer = Math.round(icon * 1.85f);
        int inner = Math.round(icon * 1.35f);
        View outerRing = ring(activity, density, true, ink);
        View innerRing = ring(activity, density, false, ink);
        root.addView(outerRing, new FrameLayout.LayoutParams(outer, outer, Gravity.CENTER));
        root.addView(innerRing, new FrameLayout.LayoutParams(inner, inner, Gravity.CENTER));
        RotateAnimation clockwise = spin(0f, 360f, 22000);
        RotateAnimation counter = spin(360f, 0f, 16000);
        track(running, outerRing, clockwise);
        track(running, innerRing, counter);

        View cross = new View(activity) {
            private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);
            @Override
            protected void onDraw(Canvas canvas) {
                paint.setColor(dye(ink, 0x33));
                paint.setStrokeWidth(density);
                float cx = getWidth() / 2f;
                float cy = getHeight() / 2f;
                canvas.drawLine(0, cy, getWidth(), cy, paint);
                canvas.drawLine(cx, 0, cx, getHeight(), paint);
            }
        };
        root.addView(cross, new FrameLayout.LayoutParams(outer, outer, Gravity.CENTER));
        cross.setAlpha(0f);
        cross.setScaleX(0.2f);
        cross.setScaleY(0.2f);
        cross.animate().alpha(1f).scaleX(1f).scaleY(1f).setStartDelay(180).setDuration(420)
                .setInterpolator(new DecelerateInterpolator()).start();

        ImageView mark = koala(activity, root, icon, art);
        mark.setAlpha(0f);
        mark.setScaleX(0.82f);
        mark.setScaleY(0.82f);
        mark.animate().alpha(1f).scaleX(1f).scaleY(1f).setStartDelay(300).setDuration(500)
                .setInterpolator(new DecelerateInterpolator()).start();
    }

    private static View ring(Activity activity, float density, boolean dashed, int ink) {
        return new View(activity) {
            private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);
            @Override
            protected void onDraw(Canvas canvas) {
                paint.setStyle(Paint.Style.STROKE);
                paint.setStrokeWidth(density);
                paint.setColor(dashed ? dye(ink, 0x33) : dye(ink, 0x66));
                if (dashed) paint.setPathEffect(new DashPathEffect(new float[]{ 6f * density, 7f * density }, 0));
                float r = Math.min(getWidth(), getHeight()) / 2f - density;
                canvas.drawCircle(getWidth() / 2f, getHeight() / 2f, r, paint);
            }
        };
    }

    private static RotateAnimation spin(float from, float to, long duration) {
        RotateAnimation animation = new RotateAnimation(from, to,
                Animation.RELATIVE_TO_SELF, 0.5f, Animation.RELATIVE_TO_SELF, 0.5f);
        animation.setDuration(duration);
        animation.setRepeatCount(Animation.INFINITE);
        animation.setInterpolator(new LinearInterpolator());
        return animation;
    }

    private static void buildCircle(Activity activity, FrameLayout root, float density, int icon, ArrayList<Object> running, int ink, Bitmap art) {
        root.setBackgroundColor(0xFF0E1117);
        int disc = Math.round(icon * 1.28f);
        View pedestal = new View(activity);
        GradientDrawable shape = new GradientDrawable();
        shape.setShape(GradientDrawable.OVAL);
        float[] hsv = new float[3];
        Color.colorToHSV(ink, hsv);
        float value = hsv[2];
        hsv[2] = Math.max(0.16f, value * 0.32f);
        shape.setColor(Color.HSVToColor(hsv));
        hsv[2] = Math.min(1f, Math.max(0.42f, value * 0.72f));
        shape.setStroke(Math.max(1, Math.round(density)), Color.HSVToColor(hsv));
        pedestal.setBackground(shape);
        root.addView(pedestal, new FrameLayout.LayoutParams(disc, disc, Gravity.CENTER));
        pedestal.setAlpha(0f);
        pedestal.setScaleX(0.75f);
        pedestal.setScaleY(0.75f);
        pedestal.animate().alpha(1f).scaleX(1f).scaleY(1f).setDuration(450)
                .setInterpolator(new DecelerateInterpolator()).start();

        ImageView mark = koala(activity, root, Math.round(icon * 0.92f), art);
        mark.setAlpha(0f);
        mark.setTranslationY(14f * density);
        mark.setScaleX(0.92f);
        mark.setScaleY(0.92f);
        mark.animate().alpha(1f).translationY(0f).scaleX(1f).scaleY(1f).setStartDelay(160).setDuration(480)
                .setInterpolator(new DecelerateInterpolator()).start();
    }

    private static void buildRipple(Activity activity, FrameLayout root, float density, int icon, ArrayList<Object> running, int ink, Bitmap art) {
        root.setBackgroundColor(0xFF070A0E);
        int size = Math.round(icon * 1.15f);
        for (int i = 0; i < 3; i++) {
            View wave = ring(activity, density, false, ink);
            root.addView(wave, new FrameLayout.LayoutParams(size, size, Gravity.CENTER));
            long delay = i * 800L;
            ObjectAnimator scaleX = ObjectAnimator.ofFloat(wave, "scaleX", 0.65f, 2.15f);
            ObjectAnimator scaleY = ObjectAnimator.ofFloat(wave, "scaleY", 0.65f, 2.15f);
            ObjectAnimator alpha = ObjectAnimator.ofFloat(wave, "alpha", 0.75f, 0f);
            for (ObjectAnimator animator : new ObjectAnimator[]{ scaleX, scaleY, alpha }) {
                animator.setDuration(2400);
                animator.setStartDelay(delay);
                animator.setRepeatCount(ValueAnimator.INFINITE);
                animator.setInterpolator(new DecelerateInterpolator());
                track(running, animator);
            }
        }
        ImageView mark = koala(activity, root, icon, art);
        mark.setAlpha(0f);
        mark.setScaleX(0.9f);
        mark.setScaleY(0.9f);
        mark.animate().alpha(1f).scaleX(1f).scaleY(1f).setStartDelay(120).setDuration(600)
                .setInterpolator(new DecelerateInterpolator()).start();
    }

    private static LinearLayout colourRow(Activity activity) {
        LinearLayout row = new LinearLayout(activity);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setGravity(Gravity.CENTER_VERTICAL);
        return row;
    }

    private static LinearLayout.LayoutParams colourChip(Activity activity) {
        int size = Math.round(34 * activity.getResources().getDisplayMetrics().density);
        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(size, size);
        params.rightMargin = Math.round(6 * activity.getResources().getDisplayMetrics().density);
        return params;
    }

    /** One even row. Every chip gets the same square and nothing wraps. */
    private static final class FitRow extends ViewGroup {
        private final int gap;

        FitRow(Context context) {
            super(context);
            gap = Math.round(4 * context.getResources().getDisplayMetrics().density);
        }

        @Override
        protected void onMeasure(int widthMeasureSpec, int heightMeasureSpec) {
            int width = MeasureSpec.getSize(widthMeasureSpec);
            int count = Math.max(1, getChildCount());
            int child = Math.max(1, (width - gap * (count - 1)) / count);
            int spec = MeasureSpec.makeMeasureSpec(child, MeasureSpec.EXACTLY);
            for (int i = 0; i < getChildCount(); i++) {
                getChildAt(i).measure(spec, spec);
            }
            setMeasuredDimension(width, child);
        }

        @Override
        protected void onLayout(boolean changed, int left, int top, int right, int bottom) {
            int x = 0;
            for (int i = 0; i < getChildCount(); i++) {
                View child = getChildAt(i);
                child.layout(x, 0, x + child.getMeasuredWidth(), child.getMeasuredHeight());
                x += child.getMeasuredWidth() + gap;
            }
        }
    }

    /** Wraps children onto the next line so the picker never scrolls sideways. */
    private static final class Flow extends ViewGroup {
        private final int gap;

        Flow(Context context, float density) {
            super(context);
            gap = Math.round(8 * density);
        }

        @Override
        protected void onMeasure(int widthMeasureSpec, int heightMeasureSpec) {
            int width = MeasureSpec.getSize(widthMeasureSpec);
            int x = 0;
            int y = 0;
            int rowHeight = 0;
            for (int i = 0; i < getChildCount(); i++) {
                View child = getChildAt(i);
                measureChild(child, widthMeasureSpec, heightMeasureSpec);
                int childWidth = child.getMeasuredWidth();
                if (x > 0 && x + childWidth > width) {
                    x = 0;
                    y += rowHeight + gap;
                    rowHeight = 0;
                }
                x += childWidth + gap;
                rowHeight = Math.max(rowHeight, child.getMeasuredHeight());
            }
            setMeasuredDimension(width, y + rowHeight);
        }

        @Override
        protected void onLayout(boolean changed, int left, int top, int right, int bottom) {
            int width = right - left;
            int x = 0;
            int y = 0;
            int rowHeight = 0;
            for (int i = 0; i < getChildCount(); i++) {
                View child = getChildAt(i);
                int childWidth = child.getMeasuredWidth();
                int childHeight = child.getMeasuredHeight();
                if (x > 0 && x + childWidth > width) {
                    x = 0;
                    y += rowHeight + gap;
                    rowHeight = 0;
                }
                child.layout(x, y, x + childWidth, y + childHeight);
                x += childWidth + gap;
                rowHeight = Math.max(rowHeight, childHeight);
            }
        }
    }

    private static final class WheelChip extends View {
        private final String[] chosen;
        private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);

        WheelChip(Context context, String[] chosen) {
            super(context);
            this.chosen = chosen;
        }

        @Override
        protected void onDraw(Canvas canvas) {
            float cx = getWidth() / 2f;
            float cy = getHeight() / 2f;
            float radius = Math.min(cx, cy) - 1f;
            paint.setShader(new SweepGradient(cx, cy, new int[]{
                    0xFFFF3B30, 0xFFFFCC00, 0xFF34C759, 0xFF007AFF, 0xFFAF52DE, 0xFFFF3B30
            }, null));
            canvas.drawCircle(cx, cy, radius, paint);
            paint.setShader(null);
            if (chosen[0] != null && chosen[0].startsWith("#")) {
                paint.setStyle(Paint.Style.STROKE);
                paint.setStrokeWidth(2f * getResources().getDisplayMetrics().density);
                paint.setColor(0xFFF8FAFC);
                canvas.drawCircle(cx, cy, radius - paint.getStrokeWidth(), paint);
                paint.setStyle(Paint.Style.FILL);
            }
        }
    }

    private static final class HueBar extends View {
        private final float[] hue;
        private final Runnable changed;
        private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);

        HueBar(Context context, float[] hue, Runnable changed) {
            super(context);
            this.hue = hue;
            this.changed = changed;
        }

        @Override
        protected void onDraw(Canvas canvas) {
            paint.setShader(new LinearGradient(0, 0, getWidth(), 0, new int[]{
                    0xFFFF0000, 0xFFFFFF00, 0xFF00FF00, 0xFF00FFFF, 0xFF0000FF, 0xFFFF00FF, 0xFFFF0000
            }, null, Shader.TileMode.CLAMP));
            float radius = getHeight() / 2f;
            canvas.drawRoundRect(0, 0, getWidth(), getHeight(), radius, radius, paint);
            paint.setShader(null);
            paint.setColor(0xFFF8FAFC);
            float x = hue[0] / 360f * getWidth();
            canvas.drawCircle(Math.max(radius, Math.min(getWidth() - radius, x)), radius, radius - 2f, paint);
        }

        @Override
        public boolean onTouchEvent(android.view.MotionEvent event) {
            hue[0] = Math.max(0f, Math.min(359f, event.getX() / Math.max(1, getWidth()) * 360f));
            changed.run();
            invalidate();
            return true;
        }
    }

    private static final class ValueBar extends View {
        private final float[] hue;
        private final float[] value;
        private final float saturation;
        private final Runnable changed;
        private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);

        ValueBar(Context context, float[] hue, float[] value, float saturation, Runnable changed) {
            super(context);
            this.hue = hue;
            this.value = value;
            this.saturation = saturation;
            this.changed = changed;
        }

        @Override
        protected void onDraw(Canvas canvas) {
            int full = Color.HSVToColor(new float[]{ hue[0], saturation, 1f });
            paint.setShader(new LinearGradient(0, 0, getWidth(), 0,
                    new int[]{ 0xFF000000, full }, null, Shader.TileMode.CLAMP));
            float radius = getHeight() / 2f;
            canvas.drawRoundRect(0, 0, getWidth(), getHeight(), radius, radius, paint);
            paint.setShader(null);
            paint.setColor(0xFFF8FAFC);
            float x = value[0] * getWidth();
            canvas.drawCircle(Math.max(radius, Math.min(getWidth() - radius, x)), radius, radius - 2f, paint);
        }

        @Override
        public boolean onTouchEvent(android.view.MotionEvent event) {
            value[0] = Math.max(0f, Math.min(1f, event.getX() / Math.max(1, getWidth())));
            changed.run();
            invalidate();
            return true;
        }
    }
}
